import re

from hbstock.api import handlers
from hbstock.api.http import Request, Response
from hbstock.config import DEFAULTS
from hbstock.market.client import StockpushClient
from hbstock.models import Conflict, NotFound, VendorError
from hbstock.services.alerts import LowStockAlerts
from hbstock.services.inventory import InventoryService
from hbstock.services.listing import ListingService
from hbstock.services.orders import OrderService
from hbstock.services.sync import SyncService
from hbstock.store.repository import StockRepository
from hbstock.util.cache import TTLCache

ROUTES = [
    ("POST", r"^/products$", handlers.create_product),
    ("GET", r"^/products/(?P<sku>[^/]+)$", handlers.get_product),
    ("POST", r"^/products/(?P<sku>[^/]+)/receive$", handlers.receive_stock),
    ("POST", r"^/products/(?P<sku>[^/]+)/count$", handlers.count_stock),
    ("POST", r"^/orders$", handlers.place_order),
    ("POST", r"^/orders/(?P<order_id>[^/]+)/ship$", handlers.ship_order),
    ("POST", r"^/orders/(?P<order_id>[^/]+)/cancel$", handlers.cancel_order),
    ("POST", r"^/market/sync$", handlers.run_sync),
    ("GET", r"^/market/listing$", handlers.market_listing),
    ("GET", r"^/reports/market-drift$", handlers.market_drift),
    ("GET", r"^/reports/low-stock$", handlers.low_stock),
]


class App:
    def __init__(self, settings, repo, services):
        self.settings = settings
        self.repo = repo
        self.services = services
        self._routes = [(m, re.compile(p), h) for m, p, h in ROUTES]

    def handle(self, request):
        for method, pattern, handler in self._routes:
            match = pattern.match(request.path)
            if match and method == request.method:
                try:
                    return handler(self, request, **match.groupdict())
                except NotFound as exc:
                    return Response.error(404, str(exc))
                except Conflict as exc:
                    return Response.error(409, str(exc))
                except VendorError as exc:
                    return Response.error(502, str(exc))
                except ValueError as exc:
                    return Response.error(400, str(exc))
        return Response.error(404, f"no route for {request.method} {request.path}")

    def get(self, path, query=None):
        return self.handle(Request("GET", path, dict(query or {}), None))

    def post(self, path, body=None, query=None):
        return self.handle(Request("POST", path, dict(query or {}), body))


def build_app(clock=None, **overrides):
    settings = DEFAULTS.with_overrides(**overrides)
    repo = StockRepository()
    client = StockpushClient(settings)
    listing = ListingService(repo, client, settings, TTLCache(settings.listing_cache_ttl, clock=clock))
    services = {
        "inventory": InventoryService(repo, settings),
        "orders": OrderService(repo),
        "alerts": LowStockAlerts(repo, settings),
        "listing": listing,
        "sync": SyncService(repo, client, settings, on_synced=listing.invalidate),
    }
    return App(settings, repo, services)
"""Endpoint handlers. Each takes (app, request, **path_params) and returns a Response."""
from hbstock.api.http import Response, bool_param


def create_product(app, request):
    product = app.services["inventory"].create(request.body or {})
    return Response(201, product.to_dict())


def receive_stock(app, request, sku):
    body = request.body or {}
    return Response.ok(app.services["inventory"].receive(sku, body.get("qty")).to_dict())


def count_stock(app, request, sku):
    body = request.body or {}
    return Response.ok(app.services["inventory"].count(sku, body.get("counted")).to_dict())


def get_product(app, request, sku):
    return Response.ok(app.services["listing"].product_view(sku.upper()))


def place_order(app, request):
    return Response(201, app.services["orders"].place(request.body or {}).to_dict())


def ship_order(app, request, order_id):
    return Response.ok(app.services["orders"].ship(order_id).to_dict())


def cancel_order(app, request, order_id):
    return Response.ok(app.services["orders"].cancel(order_id).to_dict())


def run_sync(app, request):
    return Response.ok(app.services["sync"].run(full=bool_param(request.query or {}, "full")))


def market_listing(app, request):
    return Response.ok(app.services["listing"].listing())


def market_drift(app, request):
    return Response.ok(app.services["listing"].drift())


def low_stock(app, request):
    return Response.ok({"items": app.services["alerts"].current()})
"""End-to-end: catalog -> market sync -> orders and stock counts -> sync -> market listing."""
import unittest

from tests.support import VendorHome, app_with_catalog, load_catalog, order


class MarketSyncTest(unittest.TestCase):
    def setUp(self):
        self.home = VendorHome()
        self.app = app_with_catalog(self.home, load_catalog())
        first = self.app.post("/market/sync", query={"full": "1"})
        self.assertEqual(first.status, 200, first.body)
        # a day of trading
        order(self.app, "GD-104", 2, ship=True)       # 3 -> 1 left, which is the CS unit
        order(self.app, "VC-2003", 3)                   # 4 on hand, 3 reserved
        self.app.post("/products/FD-303/count", {"counted": 0})   # shelf was empty
        order(self.app, "GD-102", 1, ship=True)        # 5 -> 4
        self.app.post("/products/GD-105/receive", {"qty": 10})    # 7 -> 17
        cancelled = order(self.app, "FD-302", 2)
        self.app.post(f"/orders/{cancelled}/cancel")
        self.sync = self.app.post("/market/sync")

    def tearDown(self):
        self.home.cleanup()

    def items(self):
        resp = self.app.get("/market/listing")
        self.assertEqual(resp.status, 200, resp.body)
        return {i["sku"]: i for i in resp.body["items"]}

    def test_sync_pushes_every_changed_product(self):
        self.assertEqual(self.sync.status, 200, self.sync.body)
        self.assertEqual(
            sorted(self.sync.body["skus"]),
            ["FD-303", "GD-102", "GD-104", "GD-105", "VC-2003"],
        )

    def test_sold_out_products_are_not_on_sale(self):
        items = self.items()
        for sku in ("GD-104", "VC-2003", "FD-303"):
            self.assertFalse(items[sku]["on_sale"], f"{sku} is sold out but still on sale in the market")
            self.assertEqual(items[sku]["market_qty"], 0, sku)

    def test_products_in_stock_show_their_quantity(self):
        items = self.items()
        expected = {"GD-101": 11, "GD-102": 3, "GD-105": 16, "VC-2001": 39, "FD-302": 5, "DG-403": 7}
        for sku, qty in expected.items():
            self.assertTrue(items[sku]["on_sale"], sku)
            self.assertEqual(items[sku]["market_qty"], qty, sku)

    def test_market_matches_our_stock(self):
        drift = self.app.get("/reports/market-drift").body
        self.assertEqual(drift["items"], [], "market quantities differ from the stock we offer")

    def test_product_page_shows_market_state(self):
        body = self.app.get("/products/gd-104").body
        self.assertEqual(body["on_hand"], 1)
        self.assertFalse(body["market"]["on_sale"], "sold-out product page still says on sale")

    def test_quiet_sync_sends_nothing(self):
        again = self.app.post("/market/sync").body
        self.assertEqual(again["lines"], 0)
        self.assertIsNone(again["transfer"])

    def test_restocked_products_go_back_on_sale_with_the_next_sync(self):
        self.app.post("/products/GD-104/receive", {"qty": 6})   # 1 -> 7 on hand
        self.app.post("/products/FD-303/receive", {"qty": 4})   # 0 -> 4 on hand
        resp = self.app.post("/market/sync")
        self.assertEqual(resp.status, 200, resp.body)
        items = self.items()
        self.assertTrue(items["GD-104"]["on_sale"], "restocked GD-104 is still off sale")
        self.assertEqual(items["GD-104"]["market_qty"], 6)
        self.assertTrue(items["FD-303"]["on_sale"], "restocked FD-303 is still off sale")
        self.assertEqual(items["FD-303"]["market_qty"], 3)
        self.assertFalse(items["VC-2003"]["on_sale"])
        self.assertEqual(self.app.get("/reports/market-drift").body["items"], [])

    def test_low_stock_alerts(self):
        alerts = {a["sku"]: a["level"] for a in self.app.get("/reports/low-stock").body["items"]}
        self.assertEqual(alerts["FD-303"], "out")
        self.assertEqual(alerts["GD-104"], "low")
        self.assertNotIn("GD-101", alerts)


if __name__ == "__main__":
    unittest.main()
